/// <summary>
/// Builds the dialog UI and registers a custom lookup method for the ItemId field.
/// </summary>
public void postBuild()
{
    super();

    DialogField dialogField = this.bindInfo().getDialogField(this.dataContractObject(), methodStr(METPackChangeSORepricingContract, parmItemId));

    if (dialogField)
    {
        dialogField.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(METPackChangeSORepricingUIBuilder, itemIdLookup), this);
    }
}

/// <summary>
/// Provides a custom lookup for the ItemId field in the dialog.
/// </summary>
/// <param name="_formStringControl">The form string control for which the lookup is being performed.</param>    
public void itemIdLookup(FormStringControl _formStringControl)
{
    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(InventTable), _formStringControl);
    Query query = new Query();
    QueryBuildDataSource qbdsInventTable, qbdsSalesLine, qbdsMetSalesLine;

    qbdsInventTable = query.addDataSource(tableNum(InventTable));

    qbdsSalesLine = qbdsInventTable.addDataSource(tableNum(SalesLine));
    qbdsSalesLine.joinMode(JoinMode::InnerJoin);
    qbdsSalesLine.addLink(fieldNum(InventTable, ItemId), fieldNum(SalesLine, ItemId));

    qbdsMetSalesLine = qbdsSalesLine.addDataSource(tableNum(METSalesLine));
    qbdsMetSalesLine.joinMode(JoinMode::InnerJoin);
    qbdsMetSalesLine.addLink(fieldNum(SalesLine, RecId), fieldNum(METSalesLine, SalesLine));

    // Add fields to display in the lookup
    sysTableLookup.addLookupfield(fieldNum(InventTable, ItemId));
    sysTableLookup.addLookupfield(fieldNum(InventTable, NameAlias));

    // Add range for SalesLine.DelayPricing = "PachChange"
    qbdsMetSalesLine.addRange(fieldNum(METSalesLine, DelayPricing)).value(queryValue(METDelayPricing::PackChange));

    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}
